class Invoice {
   private lines: Line[] = [];
-  public totalCents = 0;
+  private totalCents = 0;

+  addLine(line: Line): void {
+    if (this.issued) throw new Error('invoice already issued');
+    this.lines.push(line);
+    this.totalCents = this.lines.reduce((s, l) => s + l.amountCents, 0);
+  }
+
+  // 'de-anemized' by moving these off InvoiceService too:
+  chargeCustomer(gateway: PaymentGateway): void {
+    gateway.charge(this.customerId, this.totalCents);
+  }
+  renderPdf(renderer: PdfRenderer): Buffer {
+    return renderer.layout(this.lines, this.totalCents);
+  }
+  calculateTax(rates: TaxTable): number {
+    return rates.lookup(this.country) * this.totalCents;
+  }
 }
